"""Export the v2 tangent checker data of one Record (KernelAtlas/Tangent2K.lean).

Usage (repository root):
  python3 kernel_atlas/generators/export_v2.py <idx> <out dir> [--subs b1,b2 ...] [--all] [--labels]

Writes, next to `Data.lean` (from export_record.py):
  * `T2Data.lean`: `tcfg2 : TCfg` (the exact frame `T' = T̂ + OT`), `tq2 : TParQ`, `t2cfg : T2Cfg` (coefficients);
  * `H2Sub.lean` (with --subs) or `H2SlabNN.lean` (with --all): per sub-slab the hint list (generated by the exact
    mirror `ktangent2l.py`) and the theorem `subH cfg t2cfg leaf T1_b1 T2_b2 L3 L4 L5 hs = true` by `decide +kernel`;
  * with --labels, the leaf predicate is label membership for the v2 survivors' labels (`L2Data.lean`), else every
    depth-0 bin is accepted (`leafT`).
"""
import argparse, os, pickle, sys, time

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.abspath(os.path.join(HERE, '..', '..'))
sys.path[:0] = [HERE, os.path.join(ROOT, 'proof', 'atlas'), os.path.join(ROOT, 'explorations', 'atlas_survey')]
import kbins as KB                                                      # noqa: E402
import ktangent2 as KT2                                                 # noqa: E402
import ktangent2l as KL2                                                # noqa: E402
from export_record import mod, q_lit                                    # noqa: E402
from export_tangent import record_data, DT                              # noqa: E402


def write_t2data(outdir, base, idx, par, tc, tp, t2):
    L = []
    w = L.append
    w('import %s.Data' % mod(base))
    w('import KernelAtlas.Tangent2K')
    w('')
    w('/-! Tangent test v2 data for atlas Record %d.  Generated by `kernel_atlas/generators/export_v2.py`; do not edit. -/'
      % idx)
    w('')
    w('namespace %s' % base)
    w('')
    w('open NoFourMUBs.KernelAtlas')
    w('')
    w('/-- The exact frame `T = (T\' − OT)/DT` (only `OT` and `TpL` are used by v2). -/')
    w('def tcfg2 : TCfg where')
    w('  R := 1')
    w('  OT := %d' % tc.OT)
    flat = [tc.Tp[k][j][i] for k in range(4) for j in range(6) for i in range(6)]
    w('  TpL := [%s]' % ', '.join(str(x) for x in flat))
    for nm in ('ox', 'og', 'OX', 'OG', 'c1', 'c0', 'ke', 'g'):
        w('  %s := 0' % nm)
    w('  lv := fun _ => ⟨0, 0, 0, 0, 0, 0⟩')
    w('')
    w('def tq2 : TParQ where')
    w('  DT := %d' % DT)
    for nm, val in (('rHbar', tp.rHbar), ('nbar', tp.nbar), ('tcol', tp.tcol)):
        w('  %s := %s' % (nm, q_lit(val)))
    w('')
    w('def t2cfg : T2Cfg where')
    w('  tc := tcfg2')
    w('  ke := %d' % t2.ke)
    w('  eZ := %d' % t2.eZ)
    w('  g := 64')
    keys = ('kV', 'kU', 'kN', 'kA', 'kB', 'kG', 'kP', 'kC1', 'kC2', 'kD1', 'kD2', 'k1')
    w('  lv := fun d => match d with')
    for dd in range(4):
        w('    | %s => ⟨%s⟩' % (str(dd) if dd < 3 else '_', ', '.join(str(t2.lv[dd][k]) for k in keys)))
    skeys = ('sV', 'sR', 'sA1', 'sB1', 'sA2', 'sB2', 's1')
    w('  sc := fun d => match d with')
    for dd in range(4):
        w('    | %s => ⟨%s⟩' % (str(dd) if dd < 3 else '_', ', '.join(str(t2.sc[dd][k]) for k in skeys)))
    w('')
    w('end %s' % base)
    with open(os.path.join(outdir, 'T2Data.lean'), 'w') as f:
        f.write('\n'.join(L) + '\n')


def write_subs(outdir, base, idx, hints, subs, fname, leaf, imp):
    L = ['import %s' % imp, '',
         '/-! Record %d, tangent test v2: sub-slabs %s, one kernel declaration each (generated). -/'
         % (idx, ', '.join('(%d, %d)' % s for s in subs)), '',
         'namespace %s' % base, '', 'open NoFourMUBs.KernelAtlas', '']
    for b1, b2 in subs:
        hs = hints[(b1, b2)]
        L.append('def hs_%d_%d : List ℕ := [%s]' % (b1, b2, ', '.join(str(h) for h in hs)))
        L.append('')
        L.append('theorem sub2_%d_%d : subH cfg t2cfg %s T1_%d T2_%d L3 L4 L5 hs_%d_%d = true := by decide +kernel'
                 % (b1, b2, leaf, b1, b2, b1, b2))
        L.append('')
    L.append('end %s' % base)
    with open(os.path.join(outdir, fname), 'w') as f:
        f.write('\n'.join(L) + '\n')


def write_labels2(outdir, base, idx, S):
    """Cluster the v2 survivors (klabels.py) and write `L2Data.lean`: `labs2` and `labs2OK`."""
    import gzip, json
    import klabels as KL
    rec = json.load(gzip.open(os.path.join(ROOT, 'proof/atlas/results/atlas_certificate.json.gz'), 'rt'))['records'][idx]
    labs = KL.cluster(S, rec['label_radius'])
    L = ['import %s.T2Data' % mod(base), 'import KernelAtlas.Labels', '',
         '/-! Record %d: %d labels for the %d depth-0 survivors of the v2 bin tree (generated by `klabels.py`). -/'
         % (idx, len(labs), len(S)), '', 'namespace %s' % base, '', 'open NoFourMUBs.KernelAtlas', '',
         'def labs2 : List Lab := [']
    rows = []
    for w, sr, _ in labs:
        assert (KL.SDEN % sr.denominator) == 0
        rows.append('  ⟨%d, %d, %d, %d, %d, %d⟩' % (*w, sr.numerator * (KL.SDEN // sr.denominator)))
    L.append(',\n'.join(rows) + ']')
    L += ['', 'theorem labs2OK : labsOK labs2 = true := by decide +kernel', '', 'end %s' % base]
    with open(os.path.join(outdir, 'L2Data.lean'), 'w') as f:
        f.write('\n'.join(L) + '\n')
    return labs


def write_cover(outdir, base, idx, leaf):
    """`CoverH2.lean`: T2ParOK by kernel decision, the 144 sub-slabs, and the whole bin tree via `topH_sound`."""
    L = ['import %s.H2Slab%02d' % (mod(base), b) for b in range(12)]
    L += ['import KernelAtlas.Tangent2S', 'import KernelAtlas.Tables', '',
          '/-!', '# Record %d: the bin tree with the direct test and the hinted v2 tangent test, end to end (generated)' % idx,
          '', 'Every phase vector `β ∈ [0,1]⁵` lies in a bin that is rejected by the direct test, or by the v2 test (scalar',
          'test (6.12) or the linearised test with a hinted multiplier), for every admissible `δ` of the Record ball with the',
          'exact frame `Tmat tcfg2 tq2`, or in a depth-0 bin accepted by the leaf predicate.', '-/', '',
          'namespace %s' % base, '', 'open Hadamard6 NoFourMUBs NoFourMUBs.StageC NoFourMUBs.KernelAtlas', '',
          'theorem t2parOK : T2ParOK cfg pq t2cfg tq2 := by decide +kernel', '',
          'theorem hsubs : ∀ c1 ∈ L1, ∀ c2 ∈ L2, ∃ hs, subH cfg t2cfg %s c1 c2 L3 L4 L5 hs = true := by' % leaf,
          '  intro c1 hc1 c2 hc2',
          '  simp only [L1, List.mem_cons, List.mem_nil_iff, or_false] at hc1',
          '  simp only [L2, List.mem_cons, List.mem_nil_iff, or_false] at hc2',
          '  rcases hc1 with %s <;> rcases hc2 with %s' % (' | '.join(['rfl'] * 12), ' | '.join(['rfl'] * 12)),
          '  exacts [%s]' % ', '.join('⟨_, sub2_%d_%d⟩' % (b1, b2) for b1 in range(12) for b2 in range(12)), '',
          'theorem coverT2 {rH n r rF K : ℝ} (hK0 : 0 ≤ K)',
          '    (hK : ∀ z, cnorm (Qop ((1 / (2 * Real.pi)) • Pmat tab.pq) z) ≤ K * cnorm z)',
          '    (hKb : K ≤ pq.Kbar) (hr : r ≤ pq.rbar) (hrF : rF ≤ pq.rFbar) (hrH : rH ≤ tq2.rHbar) (hn : n ≤ tq2.nbar) :',
          '    ∀ β : I6 → ℝ, β j0 = 0 → (∀ j, 0 ≤ β j ∧ β j ≤ 1) →',
          '      Covered (Pmat tab.pq) (Tmat tcfg2 tq2) rH n r rF cfg.W0 %s β := by' % leaf,
          '  obtain ⟨hW, h1, h2, h3, h4, h5⟩ := tabB_spec tabOK',
          '  obtain ⟨r1, r2, r3, r4, r5⟩ := rootsOK',
          '  exact topH_sound parOK t2parOK hW hK0 hK hKb hr hrF hrH hn %s h1 h2 h3 h4 h5 r1 r2 r3 r4 r5 hsubs' % leaf, '',
          'end %s' % base]
    with open(os.path.join(outdir, 'CoverH2.lean'), 'w') as f:
        f.write('\n'.join(L) + '\n')


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('idx', type=int)
    ap.add_argument('out')
    ap.add_argument('--subs', nargs='*', default=[])
    ap.add_argument('--all', action='store_true')
    ap.add_argument('--labels', action='store_true')
    a = ap.parse_args()
    base = 'NoFourMUBs.KernelAtlas.Rec%d' % a.idx
    par, tc, tp, W0, R5, info = record_data(a.idx)
    t2 = KT2.TPar2(par, tc, tp.rHbar, tp.nbar, tp.tcol, KB)
    write_t2data(a.out, base, a.idx, par, tc, tp, t2)
    t0 = time.time()
    S = []
    ok, st, hints = KL2.run(par, tc, t2, W0, R5, leaf_cb=lambda acc, ts: S.append(tuple(t[0] for t in ts)) or True)
    print('mirror: %d survivors, %d hints, %.0fs' % (len(S), sum(len(v) for v in hints.values()), time.time() - t0))
    pickle.dump(dict(hints=hints, S=S), open(os.path.join(a.out, '.v2_mirror.pkl'), 'wb'))
    leaf, imp = 'leafT', '%s.T2Data' % mod(base)
    if a.labels:
        labs = write_labels2(a.out, base, a.idx, S)
        print('labels: %d' % len(labs))
        leaf, imp = '(leafL labs2)', '%s.L2Data' % mod(base)
    subs = [tuple(int(x) for x in s.split(',')) for s in a.subs]
    if subs:
        write_subs(a.out, base, a.idx, hints, subs, 'H2Sub.lean', leaf, imp)
    if a.all:
        for b1 in range(12):
            write_subs(a.out, base, a.idx, hints, [(b1, b2) for b2 in range(12)], 'H2Slab%02d.lean' % b1, leaf, imp)
        write_cover(a.out, base, a.idx, leaf)


if __name__ == '__main__':
    main()
